#include "stdlib/blas/ext/base/ndarray/dtril.h"
#include "stdlib/blas/ext/base/dtril.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/ndarray/ctor/get_ptr.h"
#include <stdio.h>

/**
* Copies the lower triangular part of a double-precision floating-point matrix `A` to another matrix `B`.
*
* @param arrays    list containing an input ndarrays
*/
void stdlib_blas_ext_dtril( const struct ndarray *arrays[] ) {
	const struct ndarray *A = arrays[ 0 ];
	const struct ndarray *B = arrays[ 1 ];
	const struct ndarray *k = arrays[ 2 ];

	const CBLAS_INT M = stdlib_ndarray_dimension( A, 0 );
	const CBLAS_INT N = stdlib_ndarray_dimension( A, 1 );

	const CBLAS_INT strideA1 = stdlib_ndarray_stride_elements( A, 0 );
	const CBLAS_INT strideA2 = stdlib_ndarray_stride_elements( A, 1 );
	const CBLAS_INT offsetA = stdlib_ndarray_offset_elements( A );

	const CBLAS_INT strideB1 = stdlib_ndarray_stride_elements( B, 0 );
	const CBLAS_INT strideB2 = stdlib_ndarray_stride_elements( B, 1 );
	const CBLAS_INT offsetB = stdlib_ndarray_offset_elements( B );

	const double *dataA = (const double *)stdlib_ndarray_data( A );
	double *dataB = (double *)stdlib_ndarray_data( B );

	CBLAS_INT k_value;
	stdlib_ndarray_get_int32(k, NULL, &k_value);

	API_SUFFIX(stdlib_strided_dtril_ndarray)( M, N, k_value, dataA, strideA1, strideA2, offsetA, dataB, strideB1, strideB2, offsetB );
}
